// Global Error Workflow (wf99) - the catch-all every active workflow points to
// via its settings.errorWorkflow field. Per Decision 3 of
// docs/99-session-notes/2026-06-01-research-review-n8n-fix-patterns.md and the
// EXECUTION-OUTCOME-OBSERVABILITY foundation: every failure becomes observable
// AND alerted, not just stored in the n8n executions DB.
//
// Allow-listed modules only (fs, path). No process.env access here (the Code-node
// sandbox blocks it per the wf30/31/32 + wf12 precedent, commit 1edb8e1 / 633755d);
// the Synology Chat URL is read by the downstream IF + HTTP nodes via the
// expression-engine $env, which is NOT sandbox-blocked.
//
// Binding: the thing that watches the system must be able to watch itself. This
// workflow has no errorWorkflow of its own set (research-review open question 1):
// if the alerter itself dies, the executions list + the watcher-cron wave 2 catch it.

const fs = require('fs');
const path = require('path');

const TELEMETRY_DIR = '/data/chatin/_telemetry/errors';
try { fs.mkdirSync(TELEMETRY_DIR, { recursive: true }); } catch (_) {}

const input = $input.first().json || {};
const wf = input.workflow || {};
const ex = input.execution || {};
const err = (ex && ex.error) || input.error || {};

const envelope = {
  workflow_id: (wf.id != null ? wf.id : ''),
  workflow_name: wf.name || '',
  node_name: ex.lastNodeExecuted || (err.node && err.node.name) || '',
  error_message: (err.message || '').toString(),
  error_stack: (err.stack || '').toString(),
  timestamp_iso: new Date().toISOString(),
  execution_id: (ex.id != null ? ex.id : '')
};

// Persist one file per failure for later analysis (keeps the _telemetry dir clean
// via the errors/ subdirectory wf12's probe telemetry sits beside).
const safeTs = envelope.timestamp_iso.replace(/[:.]/g, '-');
const filename = path.join(TELEMETRY_DIR, safeTs + '__error.json');
try { fs.writeFileSync(filename, JSON.stringify(envelope, null, 2)); } catch (_) {}

// Compose the family-readable alert line.
const alert_text = '\uD83D\uDEA8 wf' + (envelope.workflow_id || '?') + ' \u00B7 ' +
  (envelope.workflow_name || 'unknown workflow') + ' \u00B7 ' +
  (envelope.node_name || 'unknown node') + ' failed: ' +
  (envelope.error_message || 'no message') +
  ' (exec #' + (envelope.execution_id || '?') + ')';

return [{ json: { ...envelope, alert_text } }];
